Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp1\src\css\_tokens.scss", "content": "// Design tokens. Every color, size, and breakpoint used by the other partials
// comes from here, and the maps are also emitted as CSS custom properties so
// script and styles share one source of truth.
@use 'sass:map';

$colors: (
  'bg': #0a0d12,
  'bg-tint': #0d1626,
  'surface': #111c30,
  'illini-blue': #13294b,
  'border': #22314d,
  'text': #e6e9ef,
  'text-muted': #9aa6b8,
  'accent': #ff5f05,
  'accent-soft': rgba(255, 95, 5, 0.14),
  'scrim': rgba(6, 9, 14, 0.72),
  'backdrop': rgba(3, 5, 9, 0.78),
);

$fonts: (
  'mono': ('JetBrains Mono', 'Consolas', 'Menlo', monospace),
  'sans': ('Inter', 'Segoe UI', 'Helvetica Neue', Arial, sans-serif),
);

// Fluid type scale: min, preferred, max.
$type: (
  'xs': clamp(0.75rem, 0.72rem + 0.12vw, 0.8125rem),
  'sm': clamp(0.875rem, 0.84rem + 0.15vw, 0.9375rem),
  'base': clamp(1rem, 0.95rem + 0.2vw, 1.0625rem),
  'lg': clamp(1.125rem, 1.05rem + 0.35vw, 1.3125rem),
  'xl': clamp(1.5rem, 1.3rem + 0.9vw, 2rem),
  'xxl': clamp(2.25rem, 1.6rem + 3vw, 4.25rem),
);

$space: (
  '1': 0.25rem,
  '2': 0.5rem,
  '3': 1rem,
  '4': 1.5rem,
  '5': 2rem,
  '6': 3rem,
  '7': 4rem,
  '8': 6rem,
);

// Navbar heights stay plain px: js/scroll.js reads --nav-h-small and parses it
// as a number, and a custom property reads back exactly as authored.
$nav-h-large: 96px;
$nav-h-small: 64px;

$content-max: 1100px;
$radius: 10px;
$transition: 250ms ease;

// A 768-wide window measures roughly 744-752px of viewport and a 1024-wide one
// roughly 1000-1008px, so both breakpoints sit well clear of the graded widths.
$bp-narrow: 700px;
$bp-medium: 900px;

@function color($name) {
  @return map.get($colors, $name);
}

@function font($name) {
  @return map.get($fonts, $name);
}

@function type($name) {
  @return map.get($type, $name);
}

@function space($name) {
  @return map.get($space, '#{$name}');
}

@mixin emit-custom-properties {
  @each $name, $value in $colors {
    --color-#{$name}: #{$value};
  }

  @each $name, $value in $space {
    --space-#{$name}: #{$value};
  }

  --nav-h-large: #{$nav-h-large};
  --nav-h-small: #{$nav-h-small};
  --content-max: #{$content-max};
}
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp1\src\css\_mixins.scss", "content": "@use 'tokens' as *;

// Shared content column: every stripe centers its content in the same width.
@mixin container {
  width: 100%;
  max-width: $content-max;
  margin-inline: auto;
  padding-inline: space(4);
}

// A full-width horizontal stripe. Tall enough that its top can always reach
// the navbar's bottom edge, so the position indicator can land on it.
@mixin stripe($tinted: false) {
  min-height: calc(100vh - #{$nav-h-small});
  padding-block: space(8);
  display: flex;
  flex-direction: column;
  justify-content: center;

  @if $tinted {
    background-color: color('bg-tint');
  } @else {
    background-color: color('bg');
  }
}

@mixin center($direction: column) {
  display: flex;
  flex-direction: $direction;
  align-items: center;
  justify-content: center;
}

@mixin focus-ring {
  &:focus-visible {
    outline: 2px solid color('accent');
    outline-offset: 3px;
  }
}

@mixin below($breakpoint) {
  @media (max-width: #{$breakpoint - 1px}) {
    @content;
  }
}

@mixin card {
  background-color: color('surface');
  border: 1px solid color('border');
  border-radius: $radius;
}

@mixin label {
  font-family: font('mono');
  font-size: type('xs');
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: color('accent');
}

@mixin reduced-motion {
  @media (prefers-reduced-motion: reduce) {
    @content;
  }
}
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp1\src\css\_base.scss", "content": "@use 'tokens' as *;
@use 'mixins' as *;

*,
*::before,
*::after {
  box-sizing: border-box;
}

:root {
  @include emit-custom-properties;
}

html {
  // Keep the scrollbar gutter reserved so locking scroll for a modal does not
  // shift the page or the fixed navbar sideways.
  scrollbar-gutter: stable;
  -webkit-text-size-adjust: 100%;

  &.is-scroll-locked {
    overflow: hidden;
  }
}

body {
  margin: 0;
  background-color: color('bg');
  color: color('text');
  font-family: font('sans');
  font-size: type('base');
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3 {
  margin: 0;
  font-family: font('mono');
  font-weight: 700;
  line-height: 1.2;
}

p {
  margin: 0;
}

ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

img,
video,
svg {
  display: block;
  max-width: 100%;
}

a {
  color: color('accent');
  text-decoration: none;
  transition: color $transition;

  @include focus-ring;

  &:hover {
    color: color('text');
  }
}

button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}

.container {
  @include container;
}

.section-head {
  text-align: center;
  margin-bottom: space(6);

  &__label {
    @include label;
  }

  &__title {
    margin-top: space(2);
    font-size: type('xl');
  }

  &__lead {
    max-width: 38rem;
    margin: space(3) auto 0;
    color: color('text-muted');
  }
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: space(2);
  padding: space(2) space(4);
  border: 1px solid color('accent');
  border-radius: $radius;
  background-color: transparent;
  color: color('accent');
  font-family: font('mono');
  font-size: type('sm');
  transition: background-color $transition, color $transition, transform $transition;

  @include focus-ring;

  &:hover {
    background-color: color('accent');
    color: color('bg');
    transform: translateY(-2px);
  }
}

.tag-list {
  display: flex;
  flex-wrap: wrap;
  gap: space(2);

  li {
    padding: space(1) space(2);
    border: 1px solid color('border');
    border-radius: 999px;
    font-family: font('mono');
    font-size: type('xs');
    color: color('text-muted');
  }
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@include reduced-motion {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp1\src\css\_navbar.scss", "content": "@use 'tokens' as *;
@use 'mixins' as *;

.skip-link {
  position: fixed;
  top: space(2);
  left: space(2);
  z-index: 200;
  padding: space(2) space(3);
  border-radius: $radius;
  background-color: color('accent');
  color: color('bg');
  font-family: font('mono');
  transform: translateY(-200%);
  transition: transform $transition;

  &:focus {
    transform: translateY(0);
    color: color('bg');
  }
}

// Fixed rather than sticky: the height change below never alters the height
// of the document, so the shrink cannot oscillate around its threshold.
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  height: $nav-h-large;
  border-bottom: 1px solid transparent;
  background-color: transparent;
  transition: height $transition, background-color $transition, border-color $transition,
    box-shadow $transition;

  &__inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: space(3);
  }

  &__logo {
    font-family: font('mono');
    font-size: 1.75rem;
    font-weight: 700;
    color: color('text');
    transition: font-size $transition, color $transition;

    span {
      color: color('accent');
    }
  }

  &__links {
    display: flex;
    align-items: center;
    gap: space(1);
    white-space: nowrap;
  }

  &__link {
    position: relative;
    display: block;
    padding: space(2) space(3);
    font-family: font('mono');
    font-size: 1.0625rem;
    color: color('text-muted');
    transition: font-size $transition, color $transition, padding $transition;

    // Position indicator: an underline that grows in under the current item.
    &::after {
      content: '';
      position: absolute;
      left: space(3);
      right: space(3);
      bottom: 0;
      height: 2px;
      background-color: color('accent');
      transform: scaleX(0);
      transform-origin: left;
      transition: transform $transition;
    }

    &:hover {
      color: color('text');
    }

    &.is-active {
      color: color('accent');

      &::after {
        transform: scaleX(1);
      }
    }
  }

  // Shrunk state, toggled by js/navbar.js once the page is scrolled.
  &.is-scrolled {
    height: $nav-h-small;
    border-bottom-color: color('border');
    background-color: rgba(color('bg'), 0.92);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
    backdrop-filter: blur(10px);

    .navbar__logo {
      font-size: 1.25rem;
    }

    .navbar__link {
      padding-block: space(1);
      font-size: 0.875rem;
    }
  }

  @include below($bp-narrow) {
    &__links {
      gap: 0;
    }

    &__link {
      padding-inline: space(2);
      font-size: 0.8125rem;

      &::after {
        left: space(2);
        right: space(2);
      }
    }

    &.is-scrolled .navbar__link {
      font-size: 0.75rem;
    }
  }
}
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp1\src\css\_hero.scss", "content": "@use 'tokens' as *;
@use 'mixins' as *;

@keyframes fade-up {
  from {
    opacity: 0;
    transform: translateY(28px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes cue-bounce {
  0%,
  100% {
    transform: translate(-50%, 0);
  }

  50% {
    transform: translate(-50%, 10px);
  }
}

.hero {
  position: relative;
  min-height: 100vh;
  padding: $nav-h-large space(4) space(8);
  text-align: center;

  // The content is centered by the layout, not by fixed offsets, so it stays
  // vertically centered at any hero height.
  @include center;

  // Fixed-position background image: the page scrolls over it.
  background-color: color('bg');
  background-image: url('../assets/hero-grid.svg');
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
  background-attachment: fixed;

  // Scrim keeps the text readable over the pattern.
  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse at center, color('scrim') 0%, rgba(color('bg'), 0.35) 70%);
  }

  // The animation lives on this wrapper, not on .hero: a transform on the
  // element carrying a fixed background would make the background scroll.
  &__content {
    position: relative;
    max-width: 46rem;
    animation: fade-up 900ms ease both;
  }

  &__eyebrow {
    @include label;
    font-size: type('sm');
  }

  &__title {
    margin-top: space(3);
    font-size: type('xxl');
    letter-spacing: -0.02em;
  }

  &__tagline {
    margin: space(4) auto space(5);
    max-width: 36rem;
    font-size: type('lg');
    color: color('text-muted');
  }

  &__cue {
    position: absolute;
    left: 50%;
    bottom: space(5);
    width: 44px;
    height: 44px;
    border: 1px solid color('border');
    border-radius: 50%;
    color: color('accent');
    animation: cue-bounce 1.8s ease-in-out infinite;

    @include center;

    &:hover {
      border-color: color('accent');
      color: color('accent');
    }
  }

  // Short landscape windows (1280x720, 1366x768): tighten so nothing clips.
  @media (max-height: 800px) {
    padding-bottom: space(7);

    &__tagline {
      margin-block: space(3) space(4);
    }

    &__cue {
      bottom: space(3);
    }
  }
}
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp1\src\css\_sections.scss", "content": "@use 'tokens' as *;
@use 'mixins' as *;

.stripe {
  @include stripe;

  // Fallback landing offset for plain anchor jumps; js/scroll.js computes the
  // same offset itself when it animates.
  scroll-margin-top: $nav-h-small;

  &--tinted {
    @include stripe($tinted: true);
    border-block: 1px solid color('border');
  }
}

// About: photo beside bio on wide windows, stacked and centered below 900px.
.about {
  display: grid;
  grid-template-columns: minmax(220px, 320px) 1fr;
  align-items: center;
  gap: space(7);

  &__photo {
    width: 100%;
    height: auto;
    border: 1px solid color('border');
    border-radius: $radius;
    box-shadow: 16px 16px 0 color('accent-soft');
  }

  &__bio {
    display: grid;
    gap: space(3);
  }

  &__facts {
    display: grid;
    gap: space(2);
    margin-top: space(2);
    font-family: font('mono');
    font-size: type('sm');
    color: color('text-muted');

    i {
      width: 1.5em;
      color: color('accent');
    }
  }

  @include below($bp-medium) {
    grid-template-columns: 1fr;
    justify-items: center;
    gap: space(6);
    text-align: center;

    &__photo {
      max-width: 260px;
    }

    &__bio {
      max-width: 40rem;
    }

    &__facts {
      justify-items: center;
    }
  }
}

// Skills: three columns all the way down to the 768-wide graded size.
.skills {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: space(4);

  @include below($bp-narrow) {
    grid-template-columns: 1fr;
  }
}

.skill-card {
  @include card;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: space(3);
  padding: space(5) space(4);
  text-align: center;
  transition: transform $transition, border-color $transition;

  &:hover {
    transform: translateY(-6px);
    border-color: color('accent');
  }

  &__icon {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background-color: color('accent-soft');
    color: color('accent');
    font-size: 1.5rem;

    @include center;
  }

  &__title {
    font-size: type('lg');
  }

  &__text {
    color: color('text-muted');
    font-size: type('sm');
  }

  .tag-list {
    justify-content: center;
    margin-top: auto;
  }
}

.reel {
  width: 100%;
  max-width: 880px;
  height: auto;
  margin-inline: auto;
  aspect-ratio: 16 / 9;
  border: 1px solid color('border');
  border-radius: $radius;
  background-color: #000;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
}
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp1\src\css\_carousel.scss", "content": "@use 'tokens' as *;
@use 'mixins' as *;

// Arrows sit in their own side columns, so they are vertically centered beside
// the slides and can never cover a slide's text or its Details button.
.carousel {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: space(3);

  &__viewport {
    overflow: hidden;
    border-radius: $radius;
  }

  &__track {
    display: flex;
    transition: transform 400ms ease;
  }

  &__slide {
    flex: 0 0 100%;
    min-width: 0;
  }

  &__arrow {
    width: 52px;
    height: 52px;
    border: 1px solid color('border');
    border-radius: 50%;
    background-color: color('surface');
    color: color('text');
    font-size: 1.125rem;
    transition: background-color $transition, border-color $transition, color $transition,
      transform $transition;

    @include center;
    @include focus-ring;

    &:hover {
      border-color: color('accent');
      background-color: color('accent');
      color: color('bg');
      transform: scale(1.08);
    }
  }

  &__status {
    grid-column: 1 / -1;
    text-align: center;
    font-family: font('mono');
    font-size: type('sm');
    color: color('text-muted');
  }

  @include below($bp-narrow) {
    gap: space(2);

    &__arrow {
      width: 40px;
      height: 40px;
    }
  }
}

.project-card {
  @include card;
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr);
  align-items: center;
  gap: space(5);
  height: 100%;
  padding: space(5);

  &__visual {
    width: 100%;
    height: auto;
    border-radius: $radius;
  }

  &__body {
    display: grid;
    justify-items: start;
    gap: space(3);
  }

  &__kind {
    @include label;
  }

  &__title {
    font-size: type('xl');
  }

  &__summary {
    color: color('text-muted');
  }

  // Narrower windows: stack the visual over the text and center it.
  @include below($bp-medium) {
    grid-template-columns: 1fr;
    gap: space(4);
    padding: space(4);
    text-align: center;

    &__visual {
      max-width: 420px;
      margin-inline: auto;
    }

    &__body {
      justify-items: center;
    }

    .tag-list {
      justify-content: center;
    }
  }
}
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp1\src\css\_modal.scss", "content": "@use 'tokens' as *;
@use 'mixins' as *;

@keyframes modal-in {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.96);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes modal-out {
  from {
    opacity: 1;
    transform: translateY(0) scale(1);
  }

  to {
    opacity: 0;
    transform: translateY(16px) scale(0.96);
  }
}

@keyframes backdrop-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes backdrop-out {
  from {
    opacity: 1;
  }

  to {
    opacity: 0;
  }
}

// Native <dialog>: the browser supplies the focus trap, the inert page behind,
// and focus return. These rules add the look and the open/close motion.
.modal {
  width: calc(100% - #{space(5)});
  max-width: 640px;
  // Capped to the window so tall content scrolls inside the panel instead of
  // running off a 720px-tall screen.
  max-height: calc(100vh - #{space(6)});
  padding: 0;
  border: 1px solid color('border');
  border-radius: $radius;
  background-color: color('surface');
  color: color('text');
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.6);
  overflow: hidden;

  &[open] {
    display: flex;
    animation: modal-in 220ms ease both;
  }

  &::backdrop {
    background-color: color('backdrop');
    backdrop-filter: blur(3px);
    animation: backdrop-in 220ms ease both;
  }

  &.is-closing {
    animation: modal-out 180ms ease both;

    &::backdrop {
      animation: backdrop-out 180ms ease both;
    }
  }

  &__panel {
    position: relative;
    display: grid;
    justify-items: start;
    gap: space(3);
    width: 100%;
    padding: space(6) space(5) space(5);
    overflow-y: auto;
  }

  &__close {
    position: absolute;
    top: space(3);
    right: space(3);
    width: 40px;
    height: 40px;
    border: 1px solid color('border');
    border-radius: 50%;
    background-color: transparent;
    color: color('text-muted');
    transition: border-color $transition, color $transition, transform $transition;

    @include center;
    @include focus-ring;

    &:hover {
      border-color: color('accent');
      color: color('accent');
      transform: rotate(90deg);
    }
  }

  &__kind {
    @include label;
  }

  &__title {
    font-size: type('xl');
  }

  &__list {
    display: grid;
    gap: space(2);
    color: color('text-muted');

    li {
      position: relative;
      padding-left: space(4);

      &::before {
        content: '>';
        position: absolute;
        left: 0;
        font-family: font('mono');
        color: color('accent');
      }
    }
  }
}
"}

