Write {"file_path": "C:\Users\User\AppData\Local\Temp\claude\C--Users-User-Dropbox-UIUC-2026-Fall-CS-409-Art-of-Web-Programming-mp1\39c2764e-f378-4265-ba09-eaeed14656e2\scratchpad\cdp.mjs", "content": "// Minimal Chrome DevTools Protocol driver using only Node built-ins.
// Scratch verification tooling; not part of the project.
import { spawn } from 'node:child_process';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';

export async function launch(port = 9333) {
  const profile = mkdtempSync(join(tmpdir(), 'cdp-profile-'));
  const proc = spawn(CHROME, [
    '--headless=new', `--remote-debugging-port=${port}`, `--user-data-dir=${profile}`,
    '--no-first-run', '--disable-gpu', '--hide-scrollbars=false', 'about:blank',
  ], { stdio: 'ignore' });

  let target;
  for (let i = 0; i < 50; i += 1) {
    try {
      const list = await (await fetch(`http://127.0.0.1:${port}/json`)).json();
      target = list.find((t) => t.type === 'page');
      if (target) break;
    } catch (e) { /* not up yet */ }
    await new Promise((r) => setTimeout(r, 200));
  }
  if (!target) throw new Error('Chrome did not start');

  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
  let id = 0;
  const pending = new Map();
  const events = [];
  ws.onmessage = (msg) => {
    const data = JSON.parse(msg.data);
    if (data.id && pending.has(data.id)) {
      const { resolve, reject } = pending.get(data.id);
      pending.delete(data.id);
      if (data.error) reject(new Error(JSON.stringify(data.error))); else resolve(data.result);
    } else if (data.method) {
      events.push(data);
    }
  };
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    id += 1;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });

  await send('Page.enable');
  await send('Runtime.enable');
  await send('Network.enable');
  await send('Log.enable');

  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const api = {
    send, events, sleep,
    async size(width, height) {
      await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile: false });
    },
    async goto(url) {
      await send('Page.navigate', { url });
      await sleep(1800);
    },
    async eval(expression) {
      const r = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
      if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails));
      return r.result.value;
    },
    async shot(file) {
      const r = await send('Page.captureScreenshot', { format: 'png' });
      writeFileSync(file, Buffer.from(r.data, 'base64'));
    },
    async key(key, code, keyCode) {
      await send('Input.dispatchKeyEvent', { type: 'keyDown', key, code, windowsVirtualKeyCode: keyCode });
      await send('Input.dispatchKeyEvent', { type: 'keyUp', key, code, windowsVirtualKeyCode: keyCode });
    },
    async click(x, y) {
      await send('Input.dispatchMouseEvent', { type: 'mousePressed', x, y, button: 'left', clickCount: 1 });
      await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x, y, button: 'left', clickCount: 1 });
    },
    async wheel(x, y, deltaY) {
      await send('Input.dispatchMouseEvent', { type: 'mouseWheel', x, y, deltaX: 0, deltaY });
    },
    async close() {
      try { await send('Browser.close'); } catch (e) { /* already gone */ }
      proc.kill();
    },
  };
  return api;
}
"}

Write {"file_path": "C:\Users\User\AppData\Local\Temp\claude\C--Users-User-Dropbox-UIUC-2026-Fall-CS-409-Art-of-Web-Programming-mp1\39c2764e-f378-4265-ba09-eaeed14656e2\scratchpad\check_layout.mjs", "content": "// Layout checks for the static page at the five graded sizes.
import { launch } from './cdp.mjs';
import { mkdirSync } from 'node:fs';

const URL = process.argv[2] || 'http://127.0.0.1:8137/cs409-mp1/';
const OUT = process.argv[3] || './shots';
mkdirSync(OUT, { recursive: true });

const SIZES = [[1920, 1080], [1366, 768], [1280, 720], [1024, 768], [768, 1024]];
const b = await launch();
let failures = 0;
const check = (label, ok, detail = '') => {
  if (!ok) failures += 1;
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${detail ? '  -> ' + detail : ''}`);
};

for (const [w, h] of SIZES) {
  await b.size(w, h);
  await b.goto(URL);
  console.log(`\n== ${w}x${h} ==`);
  const m = await b.eval(`(() => {
    const q = (s) => document.querySelector(s);
    const qa = (s) => [...document.querySelectorAll(s)];
    const r = (el) => el.getBoundingClientRect();
    const links = qa('[data-nav-link]');
    const hero = q('.hero'), content = q('.hero__content');
    const hr = r(hero), cr = r(content);
    const skills = qa('.skill-card');
    const photo = r(q('.about__photo')), bio = r(q('.about__bio'));
    const stripes = qa('main > section');
    const navSmall = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--nav-h-small'));
    return {
      inner: innerWidth,
      overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth,
      navTops: [...new Set(links.map((a) => Math.round(r(a).top)))].length,
      navRight: Math.max(...links.map((a) => r(a).right)),
      logoRight: r(q('.navbar__logo')).right,
      firstLinkLeft: r(links[0]).left,
      heroCenterDelta: Math.abs((cr.top + cr.height / 2) - (hr.top + 96 + (hr.height - 96 - parseFloat(getComputedStyle(hero).paddingBottom)) / 2)),
      heroContentTop: cr.top, heroContentBottom: cr.bottom, heroBottom: hr.bottom,
      cueTop: r(q('.hero__cue')).top,
      skillCols: [...new Set(skills.map((s) => Math.round(r(s).left)))].length,
      aboutSideBySide: Math.abs(photo.top - bio.top) < photo.height && photo.right <= bio.left + 1,
      stripeHeights: stripes.map((s) => Math.round(r(s).height)),
      minStripe: innerHeight - navSmall,
      fontsReady: document.fonts.status,
      heroFont: getComputedStyle(q('.hero__title')).fontFamily.split(',')[0],
      faLoaded: getComputedStyle(q('.fa-solid'), '::before').content !== 'none',
      bgAttachment: getComputedStyle(hero).backgroundAttachment,
    };
  })()`);
  check('no horizontal overflow', m.overflowX <= 0, `overflow ${m.overflowX}px (innerWidth ${m.inner})`);
  check('navbar links on one line', m.navTops === 1);
  check('navbar fits beside logo', m.firstLinkLeft > m.logoRight && m.navRight <= m.inner, `logoRight ${Math.round(m.logoRight)} firstLink ${Math.round(m.firstLinkLeft)} navRight ${Math.round(m.navRight)}`);
  check('hero content vertically centered in its free area', m.heroCenterDelta < 2, `delta ${m.heroCenterDelta.toFixed(1)}px`);
  check('hero text clear of navbar and scroll cue', m.heroContentTop >= 96 && m.heroContentBottom <= m.cueTop, `top ${Math.round(m.heroContentTop)} bottom ${Math.round(m.heroContentBottom)} cue ${Math.round(m.cueTop)}`);
  check('skills has 3 columns', m.skillCols >= 3, `${m.skillCols} columns`);
  check(w >= 1024 ? 'about is side by side' : 'about is stacked', w >= 1024 ? m.aboutSideBySide : !m.aboutSideBySide);
  check('every stripe >= viewport minus small navbar', m.stripeHeights.every((s) => s >= m.minStripe - 1), `${m.stripeHeights} vs ${m.minStripe}`);
  check('fixed background attachment', m.bgAttachment === 'fixed');
  check('webfont + FontAwesome applied', m.heroFont.includes('JetBrains') && m.faLoaded, `${m.heroFont} fa=${m.faLoaded}`);
  await b.shot(`${OUT}/${w}x${h}-top.png`);
  for (const id of ['about', 'skills', 'projects', 'reel', 'contact']) {
    await b.eval(`window.scrollTo(0, document.getElementById('${id}').offsetTop - 64)`);
    await b.sleep(250);
    await b.shot(`${OUT}/${w}x${h}-${id}.png`);
  }
}

const failed = b.events.filter((e) => e.method === 'Network.loadingFailed' || (e.method === 'Network.responseReceived' && e.params.response.status >= 400));
check('no failed network requests', failed.length === 0, failed.map((e) => e.params.response?.url || e.params.errorText).join(', '));
const errors = b.events.filter((e) => e.method === 'Runtime.exceptionThrown' || (e.method === 'Log.entryAdded' && e.params.entry.level === 'error'));
check('no console errors', errors.length === 0, JSON.stringify(errors.map((e) => e.params.entry?.text || e.params.exceptionDetails?.text)).slice(0, 400));

await b.close();
console.log(`\n${failures === 0 ? 'ALL PASS' : failures + ' FAILURE(S)'}`);
process.exit(failures === 0 ? 0 : 1);
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp1\tests\geometry.test.mjs", "content": "import test from 'node:test';
import assert from 'node:assert/strict';

import {
  activeSectionIndex,
  scrollTargetY,
  scrollDuration,
  easeInOutCubic,
} from '../src/js/lib/geometry.js';

// Three sections, each 900px tall, measured in viewport coordinates.
const sections = (scrollY) => [0, 900, 1800].map((top) => ({
  top: top - scrollY,
  bottom: top + 900 - scrollY,
}));

test('activeSectionIndex picks the section under the navbar bottom edge', () => {
  // Page scrolled 936px with a 64px navbar: the edge sits 1000px down the page.
  assert.equal(activeSectionIndex(sections(936), 64, false), 1);
});

test('activeSectionIndex treats a top within 1px of the edge as current', () => {
  const almost = [{ top: -835.4, bottom: 64.6 }, { top: 64.6, bottom: 964.6 }];
  assert.equal(activeSectionIndex(almost, 64, false), 1);

  const notYet = [{ top: -834, bottom: 66 }, { top: 66, bottom: 966 }];
  assert.equal(activeSectionIndex(notYet, 64, false), 0);
});

test('activeSectionIndex returns the last section at the page bottom', () => {
  // The edge is still inside the second-to-last section, as in AE1.
  assert.equal(activeSectionIndex(sections(936), 64, true), 2);
});

test('activeSectionIndex falls back to the first section at the page top', () => {
  // Large navbar (96px) over the hero, nothing scrolled.
  assert.equal(activeSectionIndex(sections(0), 96, false), 0);
  // Edge above every section top still resolves to the first section.
  assert.equal(activeSectionIndex([{ top: 200, bottom: 1100 }], 96, false), 0);
});

test('activeSectionIndex returns -1 when there are no sections', () => {
  assert.equal(activeSectionIndex([], 64, false), -1);
  assert.equal(activeSectionIndex([], 64, true), -1);
});

test('scrollTargetY lands the section top flush under the small navbar', () => {
  assert.equal(scrollTargetY(1800, 64, 5000), 1736);
});

test('scrollTargetY clamps to the scrollable range', () => {
  assert.equal(scrollTargetY(0, 64, 5000), 0);
  assert.equal(scrollTargetY(4990, 64, 4200), 4200);
});

test('scrollDuration scales with distance between 400 and 900 ms', () => {
  assert.equal(scrollDuration(100), 400);
  assert.equal(scrollDuration(10000), 900);
  assert.equal(scrollDuration(-10000), 900);
  const mid = scrollDuration(2000);
  assert.ok(mid > 400 && mid < 900, `expected a mid-range duration, got ${mid}`);
});

test('easeInOutCubic is anchored, symmetric, monotonic, and clamped', () => {
  assert.equal(easeInOutCubic(0), 0);
  assert.equal(easeInOutCubic(1), 1);
  assert.equal(easeInOutCubic(0.5), 0.5);
  assert.equal(easeInOutCubic(-3), 0);
  assert.equal(easeInOutCubic(7), 1);

  let previous = 0;
  for (let step = 1; step <= 100; step += 1) {
    const value = easeInOutCubic(step / 100);
    assert.ok(value >= previous, `not monotonic at ${step / 100}`);
    previous = value;
  }
});
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp1\src\js\lib\geometry.js", "content": "/*
 * Pure layout math shared by the behavior modules. Nothing here touches the
 * DOM, so it is unit tested directly in tests/geometry.test.mjs.
 */

const EDGE_TOLERANCE = 1;
const MIN_SCROLL_MS = 400;
const MAX_SCROLL_MS = 900;
const MS_PER_PIXEL = 0.25;

/**
 * Index of the section lying directly under the navbar's bottom edge.
 *
 * @param {{top: number, bottom: number}[]} rects section edges in viewport coordinates
 * @param {number} navBottom the navbar's bottom edge in viewport coordinates
 * @param {boolean} atBottom whether the page is scrolled to its end
 * @returns {number} the active index, or -1 when there are no sections
 */
export function activeSectionIndex(rects, navBottom, atBottom) {
  if (rects.length === 0) {
    return -1;
  }
  // A short last section can never reach the navbar, so the end of the page
  // always belongs to it.
  if (atBottom) {
    return rects.length - 1;
  }
  const edge = navBottom + EDGE_TOLERANCE;
  const index = rects.findIndex((rect) => rect.top <= edge && rect.bottom > navBottom);
  return index === -1 ? 0 : index;
}

/**
 * Scroll position that lands a section's top flush under the small navbar.
 */
export function scrollTargetY(sectionTop, smallNavHeight, maxScroll) {
  return Math.min(Math.max(sectionTop - smallNavHeight, 0), maxScroll);
}

/**
 * Animation length for a scroll of the given distance: longer trips take
 * longer, within fixed bounds so no trip feels instant or sluggish.
 */
export function scrollDuration(distance) {
  const scaled = Math.abs(distance) * MS_PER_PIXEL;
  return Math.min(Math.max(scaled, MIN_SCROLL_MS), MAX_SCROLL_MS);
}

/**
 * Cubic ease-in-out over progress 0..1; out-of-range progress is clamped.
 */
export function easeInOutCubic(progress) {
  const t = Math.min(Math.max(progress, 0), 1);
  return t < 0.5 ? 4 * t * t * t : 1 - ((-2 * t + 2) ** 3) / 2;
}
"}

