};

for (const [w, h] of [[1920, 1080], [768, 1024]]) {
  console.log(`\n== ${w}x${h} ==`);
  await b.size(w, h);
  await b.goto(URL);

  // AE2: large at top, small after scrolling, large again at top.
  const top = await state();
  check('AE2 large navbar at the top', top.navHeight === 96 && !top.scrolled && top.active.join() === 'Home', JSON.stringify(top));
  await b.eval('window.scrollTo(0, 300)');
  await b.sleep(120);
  const mid = await state();
  check('AE2 navbar is mid-transition shortly after scrolling (animated)', mid.navHeight < 96 && mid.navHeight > 64, `height ${mid.navHeight}`);
  await b.sleep(500);
  const small = await state();
  check('AE2 navbar shrinks, text included', small.navHeight === 64 && small.linkFont < top.linkFont, `height ${small.navHeight}, font ${top.linkFont} -> ${small.linkFont}`);
  await b.eval('window.scrollTo(0, 0)');
