  await b.eval(`window.scrollTo(0, document.getElementById('skills').offsetTop - 64 - 5)`);
  await b.sleep(400);
  const before = await state();
  check('AE1 About still highlighted 5px before Skills reaches the navbar', before.active.join() === 'About', before.active.join());
  await b.eval('window.scrollTo(0, document.documentElement.scrollHeight)');
  await b.sleep(500);
  const bottom = await state();
  check('AE1 Contact highlighted at the very bottom', bottom.atBottom && bottom.active.join() === 'Contact', JSON.stringify(bottom));

  // AE3: every nav item, first one clicked from the top with the large navbar.
