    await b.sleep(1300);
    const end = await state();
    const geo = await b.eval(`(() => {
      const id = '${name}'.toLowerCase();
      const sec = document.getElementById(id);
      const nav = document.querySelector('[data-navbar]').getBoundingClientRect();
      const heading = sec.querySelector('h1, h2').getBoundingClientRect();
      return { secTop: Math.round(sec.getBoundingClientRect().top), navBottom: Math.round(nav.bottom), headingTop: Math.round(heading.top) };
    })()`);
    const animated = during.scrollY !== startY && during.scrollY !== end.scrollY;
    check(`AE3 click ${name}: animated, ends highlighted, heading visible`,
