/**
 * Wraps an index into 0..count-1 so stepping past either end of a list comes
 * back around. Returns 0 when the list is empty.
 */
export function wrapIndex(index, count) {
  if (count <= 0) {
    return 0;
  }
  return ((index % count) + count) % count;
}
EOF
