 86	  --nav-h-large: #{$nav-h-large};
 87	  --nav-h-small: #{$nav-h-small};
 88	  --content-max: #{$content-max};
 89	}
 90	@use 'tokens' as *;
 91	
 92	// Shared content column: every stripe centers its content in the same width.
 93	@mixin container {
 94	  width: 100%;
 95	  max-width: $content-max;
 96	  margin-inline: auto;
 97	  padding-inline: space(4);
