100	// A full-width horizontal stripe. Tall enough that its top can always reach
101	// the navbar's bottom edge, so the position indicator can land on it.
102	@mixin stripe($tinted: false) {
103	  min-height: calc(100vh - #{$nav-h-small});
104	  padding-block: space(8);
105	  display: flex;
106	  flex-direction: column;
107	  justify-content: center;
108	
109	  @if $tinted {
