1	/*
2	 * Entry point: wires each behavior module to the page once the DOM is ready.
3	 */
4	import { initNavbar } from './navbar.js';
5	import { initSmoothScroll } from './scroll.js';
6	import { initCarousels } from './carousel.js';
7	import { initModals } from './modal.js';
8	
9	const init = () => {
10	  initNavbar();
11	  initSmoothScroll();
12	  initCarousels();
13	  initModals();
14	};
