 1	/*
 2	 * Navbar resizing and the position indicator.
 3	 */
 4	import { activeSectionIndex } from './lib/geometry.js';
 5	
 6	const SCROLLED_CLASS = 'is-scrolled';
 7	const ACTIVE_CLASS = 'is-active';
 8	const SHRINK_AFTER_PX = 40;
 9	const PAGE_BOTTOM_TOLERANCE_PX = 2;
10	
11	export function initNavbar() {
12	  const navbar = document.querySelector('[data-navbar]');
13	  const links = Array.from(document.querySelectorAll('[data-nav-link]'));
14	  const sections = links.map((link) => document.querySelector(link.getAttribute('href')));
15	  if (!navbar || links.length === 0 || sections.includes(null)) {
16	    return;
17	  }
18	
19	  let activeIndex = -1;
20	  let frameRequested = false;
21	
22	  const setActive = (index) => {
23	    if (index === activeIndex) {
24	      return;
25	    }
26	    links.forEach((link, linkIndex) => {
27	      const isActive = linkIndex === index;
28	      link.classList.toggle(ACTIVE_CLASS, isActive);
29	      if (isActive) {
30	        link.setAttribute('aria-current', 'true');
31	      } else {
32	        link.removeAttribute('aria-current');
33	      }
34	    });
35	    activeIndex = index;
36	  };
37	
38	  const update = () => {
39	    frameRequested = false;
40	    navbar.classList.toggle(SCROLLED_CLASS, window.scrollY > SHRINK_AFTER_PX);
41	
42	    // Measure the navbar as it is right now: it may be mid-resize.
43	    const navBottom = navbar.getBoundingClientRect().bottom;
44	    const rects = sections.map((section) => section.getBoundingClientRect());
45	    const pageBottom = document.documentElement.scrollHeight - PAGE_BOTTOM_TOLERANCE_PX;
46	    const atBottom = window.scrollY + window.innerHeight >= pageBottom;
47	    setActive(activeSectionIndex(rects, navBottom, atBottom));
48	  };
49	
50	  // Scroll and resize fire far more often than the screen repaints, so all of
51	  // them collapse into one measurement per animation frame.
52	  const requestUpdate = () => {
53	    if (!frameRequested) {
54	      frameRequested = true;
55	      window.requestAnimationFrame(update);
56	    }
57	  };
58	
59	  window.addEventListener('scroll', requestUpdate, { passive: true });
60	  window.addEventListener('resize', requestUpdate);
61	  // The navbar's bottom edge keeps moving after the last scroll event while
62	  // its height transition finishes; measure once more when it settles.
63	  navbar.addEventListener('transitionend', (event) => {
64	    if (event.target === navbar && event.propertyName === 'height') {
65	      requestUpdate();
66	    }
67	  });
68	
69	  update();
70	}

 1	/*
 2	 * Smooth scrolling for in-page links, animated by hand with
 3	 * requestAnimationFrame. CSS scroll-behavior is deliberately left unset so the
 4	 * two never compound.
 5	 */
 6	import { scrollTargetY, scrollDuration, easeInOutCubic } from './lib/geometry.js';
 7	
 8	const INTERRUPT_EVENTS = ['wheel', 'touchstart', 'keydown'];
 9	const SCROLL_KEYS = ['ArrowUp', 'ArrowDown', 'PageUp', 'PageDown', 'Home', 'End', ' '];
10	
11	export function initSmoothScroll() {
12	  const links = Array.from(document.querySelectorAll('[data-scroll]'));
13	  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
14	  let frameId = 0;
15	
16	  // The navbar is in its small state everywhere except the very top, so the
17	  // small height is the offset every landing needs. It is defined once, in
18	  // the SCSS tokens, and read back here.
19	  const smallNavHeight = () => {
20	    const value = getComputedStyle(document.documentElement).getPropertyValue('--nav-h-small');
21	    return parseFloat(value) || 0;
22	  };
23	
24	  const stop = () => {
25	    if (frameId) {
26	      window.cancelAnimationFrame(frameId);
27	      frameId = 0;
28	    }
29	    INTERRUPT_EVENTS.forEach((name) => window.removeEventListener(name, interrupt));
30	  };
31	
32	  // The visitor always wins: scroll input of their own ends the animation.
33	  // Keys that do not scroll, such as Tab, leave it running.
34	  function interrupt(event) {
35	    if (event.type !== 'keydown' || SCROLL_KEYS.includes(event.key)) {
36	      stop();
37	    }
38	  }
39	
40	  const scrollToSection = (section) => {
41	    stop();
42	
43	    const startY = window.scrollY;
44	    const maxScroll = document.documentElement.scrollHeight - window.innerHeight;
45	    const sectionTop = section.getBoundingClientRect().top + startY;
46	    const endY = scrollTargetY(sectionTop, smallNavHeight(), maxScroll);
47	    const distance = endY - startY;
48	
49	    if (reducedMotion.matches || distance === 0) {
50	      window.scrollTo(0, endY);
51	      return;
52	    }
53	
54	    const duration = scrollDuration(distance);
55	    const startTime = performance.now();
56	
57	    const step = (now) => {
58	      const progress = (now - startTime) / duration;
59	      window.scrollTo(0, startY + distance * easeInOutCubic(progress));
60	      if (progress < 1) {
61	        frameId = window.requestAnimationFrame(step);
62	      } else {
63	        stop();
64	      }
65	    };
66	
67	    INTERRUPT_EVENTS.forEach((name) => {
68	      window.addEventListener(name, interrupt, { passive: true });
69	    });
70	    frameId = window.requestAnimationFrame(step);
71	  };
72	
73	  links.forEach((link) => {
74	    const section = document.querySelector(link.getAttribute('href'));
75	    if (!section) {
76	      return;
77	    }
78	    link.addEventListener('click', (event) => {
79	      event.preventDefault();
80	      scrollToSection(section);
81	      window.history.replaceState(null, '', link.getAttribute('href'));
82	    });
83	  });
84	}

 1	/*
 2	 * Project carousel: side arrows, wrap-around, and a slide indicator.
 3	 *
 4	 * The track is moved by CSS alone. This module only records the current slide
 5	 * in a data attribute, and _carousel.scss maps each index to a transform, so
 6	 * no inline styles are ever written.
 7	 */
 8	import { wrapIndex } from './lib/geometry.js';
 9	
10	// Longer than the CSS transition; releases the lock if transitionend is
11	// never delivered (for example when the tab is hidden mid-slide).
12	const UNLOCK_FALLBACK_MS = 700;
13	
14	function initCarousel(root) {
15	  const track = root.querySelector('[data-carousel-track]');
16	  const slides = Array.from(root.querySelectorAll('[data-carousel-slide]'));
17	  const previous = root.querySelector('[data-carousel-prev]');
18	  const next = root.querySelector('[data-carousel-next]');
19	  const status = root.querySelector('[data-carousel-status]');
20	  if (!track || slides.length === 0 || !previous || !next) {
21	    return;
22	  }
23	
24	  let current = 0;
25	  let locked = false;
26	  let fallbackTimer = 0;
27	
28	  const unlock = () => {
29	    locked = false;
30	    window.clearTimeout(fallbackTimer);
31	  };
32	
33	  const render = () => {
34	    track.dataset.index = String(current);
35	    slides.forEach((slide, index) => {
36	      // Off-screen slides leave the tab order and the accessibility tree.
37	      slide.inert = index !== current;
38	    });
39	    if (status) {
40	      status.textContent = `Slide ${current + 1} of ${slides.length}`;
41	    }
42	  };
43	
44	  const go = (step) => {
45	    // Clicks that arrive mid-transition are ignored rather than queued.
46	    if (locked) {
47	      return;
48	    }
49	    const target = wrapIndex(current + step, slides.length);
50	    if (target === current) {
51	      return;
52	    }
53	    locked = true;
54	    fallbackTimer = window.setTimeout(unlock, UNLOCK_FALLBACK_MS);
55	    current = target;
56	    render();
57	  };
58	
59	  track.addEventListener('transitionend', (event) => {
60	    if (event.target === track && event.propertyName === 'transform') {
61	      unlock();
62	    }
63	  });
64	  previous.addEventListener('click', () => go(-1));
65	  next.addEventListener('click', () => go(1));
66	
67	  render();
68	}
69	
70	export function initCarousels() {
71	  document.querySelectorAll('[data-carousel]').forEach(initCarousel);
72	}

